ncld = noise{seed=71, octaves=3, period=260}
function cloudbar(yc, th, x0, x1, ph, amp)
  local pts, ws = {}, {}
  local n = 10
  for i=0,n do
    local t = i/n
    pts[i+1] = {x0 + (x1-x0)*t, yc + amp*ncld(x0 + (x1-x0)*t, ph*97)}
    ws[i+1] = th * (0.55 + 0.55*math.sin(t*3.1 + ph))
  end
  return ribbon(pts, ws):blur(16)
end
